#include "augmatch/noise.hpp"
#include <cuda_runtime.h>
#include <cmath>
#include <cstdint>
#include <vector>
int main(){int count=0;if(cudaGetDeviceCount(&count)!=cudaSuccess||count==0)return 77;const int T=3,H=2,W=3,C=1;const size_t n=(size_t)T*H*W*C;std::vector<float> h(n,.3f),o(n);float *di=nullptr,*doo=nullptr;if(cudaMalloc(&di,n*sizeof(float))!=cudaSuccess||cudaMalloc(&doo,n*sizeof(float))!=cudaSuccess)return 77;cudaMemcpy(di,h.data(),n*sizeof(float),cudaMemcpyHostToDevice);try{std::uint8_t hs[H*W]={0,1,0,1,0,1},*ds=nullptr;cudaMalloc(&ds,sizeof(hs));cudaMemcpy(ds,hs,sizeof(hs),cudaMemcpyHostToDevice);augmatch::RandomTelegraphSignalNoiseConfig r;r.width=W;r.height=H;r.channels=C;r.state_map=ds;r.low_offset=-.1f;r.high_offset=.2f;augmatch::random_telegraph_signal_noise_f32(di,doo,r);if(cudaDeviceSynchronize()!=cudaSuccess)return 77;float rt[H*W];cudaMemcpy(rt,doo,sizeof(rt),cudaMemcpyDeviceToHost);for(int j=0;j<H*W;++j){const float expected = hs[j] ? .5f : .2f;if(fabsf(rt[j]-expected)>1e-6f)return 1;}cudaFree(ds);augmatch::InterFrameCompressionNoiseConfig c;c.frames=T;c.height=H;c.width=W;c.channels=C;c.quantization_step=.1f;c.strength=1;c.seed=4;augmatch::inter_frame_compression_noise_f32(di,doo,c);if(cudaDeviceSynchronize()!=cudaSuccess)return 77;cudaMemcpy(o.data(),doo,n*sizeof(float),cudaMemcpyDeviceToHost);for(float v:o)if(v<0||v>1)return 1;augmatch::WaterDropletsOnLensConfig w;w.width=W;w.height=H;w.channels=C;w.droplet_count=1;w.opacity=.5f;w.seed=8;augmatch::water_droplets_on_lens_f32(di,doo,w);if(cudaDeviceSynchronize()!=cudaSuccess)return 77;}catch(...){cudaFree(di);cudaFree(doo);return 77;}cudaFree(di);cudaFree(doo);return 0;}
